from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient

class FMv2HttpClient(HttpClient):
    """ This class provides a client for the FM v2 API. """
    def __init__(self, base_url, connection_alias):
        super(FMv2HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/fm/v2"

    def get_historical_alarms(self, timeout=30, page_number=None, items_per_page=None, sorted_by="appearTime",
                              sort_order="desc", filter_by_severity=None, filter_by_alarming_object=None,
                              filter_by_text=None):
        endpoint = '/alarms/historical'

        parameters = {
            "pageNumber": page_number,
            "itemsPerPage": items_per_page,
            "sortedBy": sorted_by,
            "sortOrder": sort_order,
            "filterBySeverity": filter_by_severity,
            "filterByAlarmingObject": filter_by_alarming_object,
            "filterByText": filter_by_text,
        }

        payload = {key: value for key, value in parameters.items() if value is not None}

        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)

    def get_active_alarms(self, timeout=30, page_number=None, items_per_page=None, sorted_by="appearTime",
                              sort_order="desc", filter_by_severity=None, filter_by_alarming_object=None,
                              filter_by_text=None):
        endpoint = '/alarms/active'

        parameters = {
            "pageNumber": page_number,
            "itemsPerPage": items_per_page,
            "sortedBy": sorted_by,
            "sortOrder": sort_order,
            "filterBySeverity": filter_by_severity,
            "filterByAlarmingObject": filter_by_alarming_object,
            "filterByText": filter_by_text,
        }

        payload = {key: value for key, value in parameters.items() if value is not None}

        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)
